const root = $json || {};
const envelope = root.body && typeof root.body === 'object' ? root.body : root;
const data = envelope.data && typeof envelope.data === 'object' ? envelope.data : (root.data || envelope);
const key = data.key || envelope.key || root.key || {};
const msg = data.message || envelope.message || root.message || {};

function onlyDigits(value) {
  return String(value || '').split('@')[0].replace(/\D/g, '');
}

function firstPhone(candidates) {
  for (const candidate of candidates) {
    const digits = onlyDigits(candidate);
    if (digits.length >= 10) return digits;
  }
  return '';
}

const remoteJid = String(
  key.remoteJid ||
  key.remoteJidAlt ||
  data.remoteJid ||
  data.from ||
  envelope.from ||
  root.from ||
  ''
).trim();

const phone = firstPhone([
  key.remoteJid,
  key.remoteJidAlt,
  data.remoteJid,
  data.number,
  envelope.number,
  root.number,
  data.phone,
  envelope.phone,
  root.phone,
  data.sender,
  envelope.sender,
  root.sender
]);

const text = String(
  data.text ||
  envelope.text ||
  root.text ||
  data.bodyText ||
  envelope.bodyText ||
  msg.conversation ||
  msg.extendedTextMessage?.text ||
  msg.imageMessage?.caption ||
  msg.videoMessage?.caption ||
  msg.documentMessage?.caption ||
  msg.buttonsResponseMessage?.selectedDisplayText ||
  msg.listResponseMessage?.title ||
  msg.templateButtonReplyMessage?.selectedDisplayText ||
  ''
).trim();

const messageId = String(
  key.id ||
  data.messageId ||
  data.id ||
  envelope.message_id ||
  root.message_id ||
  root.messageId ||
  root.id ||
  ''
).trim() || `${phone || 'unknown'}:${Date.now()}`;

const fromMe = Boolean(key.fromMe || data.fromMe || envelope.fromMe || root.fromMe);
const messageType = String(data.messageType || envelope.messageType || root.messageType || '').trim();
const instance = String(envelope.instance || data.instance || root.instance || $env.EVOLUTION_INSTANCE_NAME || '').trim();
const isGroup = remoteJid.includes('@g.us');
const canReply = Boolean(phone && !fromMe && !isGroup);
const isSupportedText = Boolean(text);

return [{
  json: {
    phone,
    remote_jid: remoteJid,
    message_text: text,
    message_id: messageId,
    message_type: messageType,
    push_name: data.pushName || envelope.pushName || root.pushName || data.push_name || envelope.push_name || '',
    instance,
    from_me: fromMe,
    is_group: isGroup,
    can_reply: canReply,
    is_supported_text: isSupportedText,
    is_valid_user_message: Boolean(canReply && isSupportedText),
    current_date: new Date().toLocaleDateString('sv-SE', { timeZone: 'America/Sao_Paulo' }),
    raw: root
  }
}];

options.systemMessage:
Você interpreta uma resposta de WhatsApp para uma conversa pendente do AcerttaPay.

Retorne SOMENTE JSON válido.

Se o estado for awaiting_purchase_edit_confirmation:
- confirmar/sim/pode/aplica => {"intent":"confirm_edit","confirm":true,"confidence":0.9}
- cancelar/não/deixa => {"intent":"cancel_edit","confirm":false,"confidence":0.9}

Se o estado for awaiting_purchase_delete_confirmation:
- apagar/excluir/deletar/confirmar => {"intent":"confirm_delete","confirm":true,"confidence":0.9}
- cancelar/não/deixa => {"intent":"cancel_delete","confirm":false,"confidence":0.9}

Se o estado for divisão de participantes, use os schemas do fluxo 1.1:
{"intent":"select_split_participants","confidence":0.0,"participants":["self"],"include_self":true,"mode":"equal","shares":[]}
{"intent":"exact_split","confidence":0.0,"mode":"exact","shares":[{"participant":"self","amount_cents":0}]}
{"intent":"clarification","confidence":0.0}

Nunca invente participante, cartão ou valor.

