function cleanJsonContent(value) {
  if (value && typeof value === 'object') return value;
  const raw = String(value || '').trim();
  if (!raw) return '';
  const withoutFence = raw.replace(/^```(?:json)?\s*/i, '').replace(/```$/i, '').trim();
  const first = withoutFence.indexOf('{');
  const last = withoutFence.lastIndexOf('}');
  if (first >= 0 && last > first) return withoutFence.slice(first, last + 1);
  return withoutFence;
}
const content = $json.output ?? $json.text ?? $json.response ?? $json.choices?.[0]?.message?.content ?? '';
let parsed;
try {
  const cleaned = cleanJsonContent(content);
  parsed = typeof cleaned === 'object' ? cleaned : JSON.parse(cleaned);
} catch (error) {
  parsed = null;
}
if (!parsed || typeof parsed !== 'object') {
  parsed = { intent: 'clarification', confidence: 0, needs_backend: false, reply_text: 'Não consegui entender com segurança. Me fala de novo, tipo: corrige a última compra para R$ 189,90.' };
}
return [{ json: parsed }];

const parsed = $json || {};
const conversation = $('Resolve AcerttaPay User').first().json.conversation || {};
const state = String(conversation.state || '').trim();
const payload = conversation.payload || {};
const phone = $('Normalize Evolution Payload').first().json.phone;
const source = {
  channel: 'whatsapp',
  instance: $('Normalize Evolution Payload').first().json.instance,
  message_id: $('Normalize Evolution Payload').first().json.message_id,
  raw_text: $('Normalize Evolution Payload').first().json.message_text
};
let endpoint = '/api/automation/v1/conversations/reply';
let body = { phone, source, reply: parsed };
if (state === 'awaiting_purchase_edit_confirmation') {
  endpoint = `/api/automation/v1/purchases/${payload.purchase_id || conversation.related_purchase_id || 'last'}/confirm-edit`;
  body = { phone, source, reply: parsed, patch: payload.patch || {}, confirm: parsed.confirm === true };
}
if (state === 'awaiting_purchase_delete_confirmation') {
  endpoint = `/api/automation/v1/purchases/${payload.purchase_id || conversation.related_purchase_id || 'last'}/confirm-delete`;
  body = { phone, source, reply: parsed, confirm: parsed.confirm === true };
}
return [{ json: { endpoint, body, idempotency_key: `whatsapp-correction-reply:${source.instance}:${source.message_id}` } }];

const res = $json || {};
let text = res.whatsapp?.text || res.message || 'Pedido processado no AcerttaPay.';
if (res.code === 'PURCHASE_EDITED' && res.purchase) {
  text = res.whatsapp?.text || [
    '✅ *Compra corrigida!*',
    '',
    `🧾 ${res.purchase.description || 'Compra'} — *R$ ${(Number(res.purchase.amount_cents || 0) / 100).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}*`,
    res.purchase.card_name ? `💳 Cartão: *${res.purchase.card_name}*` : '',
    res.purchase.installments ? `🔢 Parcelas: *${res.purchase.installments}x*` : ''
  ].filter(Boolean).join('\n');
}
if (res.code === 'PURCHASE_DELETED') text = res.whatsapp?.text || '🗑️ Compra apagada com sucesso.';
return [{ json: { ...res, outbound_text: text } }];

